// Per-species measured facts, regenerated by scripts/extract_species_parts.py
// together with the part OBJs (see the extract report for the raw numbers).
struct SpeciesMetrics
{
    const char *id;               // registry id (head_<id>, tail_<id>, ...)
    const char *display;          // panel label
    vec3 torsoMount;              // graft waist-ring centre on the taur body
    quat torsoMountRotation;      // the graft's top-ring frame (the trunk lean)
    float stumpRadius;            // the taur's stump ring radius (graft base)
    vec3 tailMount;               // tail socket on the normalised taur body
    quat tailMountRotation;       // maps the tail part's +Z onto the ring normal
    float tailStumpRadius;        // tail root-ring radius at taur scale
    vec3 withers;                 // wing socket pair on the taur back
    float groundY;                // taur hooves-to-origin offset (taur frame)
    float groundQuadY;            // whole-animal offset (quadruped frame)
    float lengthZ;                // taur length (bounds)
    vec3 earSocketLeft;            // ear sockets in the head frame (identity)
    quat earRotationLeft;
    vec3 earSocketRight;
    quat earRotationRight;
    bool hasEarSockets;           // false: the species keeps its ears in-mesh
    float tailRootRadius;         // natural-scale tail root ring radius
    vec3 neckTop;                  // the neck part's head-mount socket
    vec3 neckBoundsCenter;         // the neck part's bounds (fit + previews)
    float neckBoundsRadius;
    int graftRingFirst;            // waist-ring verts in quad_taur_<id> (coat)
    int graftRingCount;
};

